class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # To obtain maximum run length 1, the string must alternate.
        flips = sum(ch != ('0' if i % 2 == 0 else '1')
                    for i, ch in enumerate(s))
        if min(flips, n - flips) <= numOps:
            return 1

        # For a maximum run length L >= 2, each original run of length r
        # requires floor(r / (L + 1)) flips to split it into short runs.
        for limit in range(2, n + 1):
            needed = 0
            run = 0
            prev = ''
            for ch in s:
                if ch == prev:
                    run += 1
                else:
                    needed += run // (limit + 1)
                    prev, run = ch, 1
            needed += run // (limit + 1)
            if needed <= numOps:
                return limit

        return n

