from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(target: int) -> bool:
            # Enter index 0 on the first move.
            moves = 1
            visits = 1
            if moves > m:
                return False
            for i in range(n - 1):
                required = (target + points[i] - 1) // points[i]
                extra = max(0, required - visits)
                # Bounce across (i, i+1) extra times, then advance to i+1.
                moves += 2 * extra + 1
                if moves > m:
                    return False
                visits = extra + 1
            required = (target + points[-1] - 1) // points[-1]
            extra = max(0, required - visits)
            moves += 2 * extra
            return moves <= m

        lo, hi = 0, max(points) * (m + 1)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

