from typing import List
from math import gcd

class Solution:
    def subsequencePairCount(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        SIZE = 201
        gcd_table = [[gcd(a, b) for b in range(SIZE)] for a in range(SIZE)]

        # gcd 0 represents an empty subsequence.
        dp = [[0] * SIZE for _ in range(SIZE)]
        dp[0][0] = 1

        for x in nums:
            nxt = [[0] * SIZE for _ in range(SIZE)]
            for a, row in enumerate(dp):
                for b, ways in enumerate(row):
                    if ways:
                        # Leave this index unused, or assign it to either sequence.
                        nxt[a][b] += ways
                        nxt[gcd_table[a][x]][b] += ways
                        nxt[a][gcd_table[b][x]] += ways
            for row in nxt:
                for j, value in enumerate(row):
                    if value >= MOD:
                        row[j] = value % MOD
            dp = nxt

        return sum(dp[g][g] for g in range(1, SIZE)) % MOD

