from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        children = [{}]
        counts = [0]
        paths = []

        for word in words:
            node = 0
            path = []
            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    counts.append(0)
                node = nxt
                counts[node] += 1
                path.append(node)
            paths.append(path)

        # For each depth, track how many nodes have count >= k, and whether
        # any such node has count > k.
        qualifying = [0] * (max(map(len, words)) + 1)
        safe = [False] * len(qualifying)
        for path in paths:
            for depth, node in enumerate(path, 1):
                if counts[node] == k:
                    qualifying[depth] += 1
                elif counts[node] > k:
                    safe[depth] = True

        # A depth is vulnerable only if its sole qualifying node has count k.
        candidates = []
        vulnerable = set()
        for depth in range(1, len(qualifying)):
            if safe[depth] or qualifying[depth]:
                candidates.append(depth)
                if not safe[depth] and qualifying[depth] == 1:
                    vulnerable.add(depth)
        candidates.sort(reverse=True)

        result = []
        for path in paths:
            affected = set()
            for depth, node in enumerate(path, 1):
                if depth in vulnerable and counts[node] == k:
                    affected.add(depth)

            answer = 0
            for depth in candidates:
                if depth not in affected:
                    answer = depth
                    break
            result.append(answer)

        return result

