from typing import List
class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n=len(nums)
        g=[[] for _ in range(n)]
        for u,v,w in edges:
            g[u].append((v,w)); g[v].append((u,w))
        last=[-1]*50001
        path_dist=[0]*n
        best_len=0; best_nodes=1; left=0
        stack=[(True,0,-1,0,0,0,-1)]
        while stack:
            entering,node,parent,depth,dist,old_left,old_last=stack.pop()
            if entering:
                value=nums[node]
                old_left=left; old_last=last[value]
                left=max(left,old_last+1)
                last[value]=depth
                path_dist[depth]=dist
                length=dist-path_dist[left]
                nodes=depth-left+1
                if length>best_len:
                    best_len,best_nodes=length,nodes
                elif length==best_len and nodes<best_nodes:
                    best_nodes=nodes
                stack.append((False,node,parent,depth,dist,old_left,old_last))
                for child,w in reversed(g[node]):
                    if child!=parent:
                        stack.append((True,child,node,depth+1,dist+w,0,-1))
            else:
                left=old_left
                last[nums[node]]=old_last
        return [best_len,best_nodes]

