import sys

MOD = 998244353

def main():
    data = sys.stdin.buffer.read().split()
    N, M = map(int, data[:2])
    S = data[2].decode()

    letters = list(set(S))
    # All letters absent from S induce the same transition.
    absent_count = 26 - len(letters)
    transitions = [(ch, 1) for ch in letters]
    if absent_count:
        transitions.append((None, absent_count))

    dp = {(0,) * (N + 1): 1}
    for _ in range(M):
        ndp = {}
        for row, ways in dp.items():
            for ch, multiplicity in transitions:
                new = [0] * (N + 1)
                for j in range(1, N + 1):
                    match = ch is not None and S[j - 1] == ch
                    new[j] = max(row[j], new[j - 1], row[j - 1] + match)
                key = tuple(new)
                ndp[key] = (ndp.get(key, 0) + ways * multiplicity) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for row, ways in dp.items():
        ans[row[N]] = (ans[row[N]] + ways) % MOD
    print(*ans)

if __name__ == '__main__':
    main()

