            cand.append((m*b,c*b))
            cand.append((m,c+a))
        cand.sort()
        uniq=[]
        for m,c in cand:
            if uniq and uniq[-1][0]==m:
                if c>uniq[-1][1]: uniq[-1]=(m,c)
            else: uniq.append((m,c))
        hull=[]
        for m,c in uniq:
            while len(hull)>=2:
                m1,c1=hull[-2]; m2,c2=hull[-1]
                if (c1-c2)*(m-m2) >= (c2-c)*(m2-m1):
                    hull.pop()
                else: break
