    l=0;r=len(h)-1
    while l<r:
        mid=(l+r)//2
        if h[mid][0]*x+h[mid][1] <= h[mid+1][0]*x+h[mid+1][1]: l=mid+1
        else:r=mid
    return h[l][0]*x+h[l][1]

