class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""
        INF = 10**9
        # State (current run character, run length capped at 3), before processing i.
        # Flat rows of 26 * 3 integers.
        dp = [None] * (n + 1)
        end = [INF] * 78
        for c in range(26):
            end[c * 3 + 2] = 0
        dp[n] = end
        vals = [ord(ch) - 97 for ch in caption]
        for i in range(n - 1, -1, -1):
            nxt = dp[i + 1]
            row = [INF] * 78
            x = vals[i]
            # Switching is allowed only from a completed run; the new run has length 1.
            switch = [INF] * 26
            for c in range(26):
                best = INF
                for d in range(26):
                    if d != c:
                        v = nxt[d * 3] + abs(x - d)
                        if v < best:
                            best = v
                switch[c] = best
            for c in range(26):
                base = c * 3
                cost = abs(x - c)
                # Run lengths 1 and 2 must continue unchanged.
                row[base] = cost + nxt[base + 1]
                row[base + 1] = cost + nxt[base + 2]
                # At length >= 3, continue, or start a different run.
                row[base + 2] = min(cost + nxt[base + 2], switch[c])
            dp[i] = row

        # A valid caption may start with any character, with its first run length 1.
        first = dp[0]
        best_cost = INF
        for c in range(26):
            v = abs(vals[0] - c) + dp[1][c * 3]
            if v < best_cost:
                best_cost = v
        if best_cost >= INF:
            return ""

        # Reconstruct greedily: at each position try letters in lexicographic order,
        # retaining only choices that preserve the optimal remaining cost.
        out = []
        prev = -1
        run = 0
        remaining = best_cost
        for i, x in enumerate(vals):
            chosen = None
            for c in range(26):
                add = abs(x - c)
                if prev == -1:
                    tail = dp[i + 1][c * 3]
                elif c == prev:
                    nr = min(3, run + 1)
                    tail = dp[i + 1][c * 3 + nr - 1]
                else:
                    if run < 3:
                        continue
                    tail = dp[i + 1][c * 3]
                if add + tail == remaining:
                    chosen = c
                    remaining -= add
                    break
            if chosen is None:
                return ""
            out.append(chr(97 + chosen))
            if chosen == prev:
                run = min(3, run + 1)
            else:
                prev = chosen
                run = 1
        return ''.join(out)

