def ntt(a, invert, mod, root):
    n = len(a)

    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(root, (mod - 1) // length, mod)
        if invert:
            wlen = pow(wlen, mod - 2, mod)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % mod
                a[i] = (u + v) % mod
                a[i + half] = (u - v) % mod
                w = w * wlen % mod
        length <<= 1

    if invert:
        inv_n = pow(n, mod - 2, mod)
        for i in range(n):
            a[i] = a[i] * inv_n % mod

def convolution(freq, size, mod, root):
    a = freq + [0] * (size - len(freq))
    ntt(a, False, mod, root)
    for i in range(size):
        a[i] = a[i] * a[i] % mod
    ntt(a, True, mod, root)
    return a

