class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        offset = sum(nums)
        # product -> [bitset of sums from even-length subsequences,
        #             bitset of sums from odd-length subsequences]
        dp = {}

        for x in nums:
            old = list(dp.items())

            # Start a new subsequence with this element (length one).
            if x <= limit:
                state = dp.setdefault(x, [0, 0])
                state[1] |= 1 << (offset + x)

            # Extend each subsequence that existed before this element.
            for product, (even_sums, odd_sums) in old:
                new_product = product * x
                if new_product > limit:
                    continue
                state = dp.setdefault(new_product, [0, 0])
                # At an even-length prefix, x is added; at an odd-length prefix,
                # x is subtracted. The parity then toggles.
                state[1] |= even_sums << x
                state[0] |= odd_sums >> x

        target = offset + k
        if target < 0 or target > 2 * offset:
            return -1
        target_bit = 1 << target

        for product in range(limit, -1, -1):
            state = dp.get(product)
            if state is not None and ((state[0] | state[1]) & target_bit):
                return product
        return -1

