class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side
        positions = []
        for x, y in points:
            if x == 0:
                t = y
            elif y == side:
                t = side + x
            elif x == side:
                t = 3 * side - y
            else:  # y == 0
                t = 4 * side - x
            positions.append(t % perimeter)

        positions.sort()
        n = len(positions)
        extended = (positions +
                    [x + perimeter for x in positions] +
                    [x + 2 * perimeter for x in positions])

        def feasible(distance: int) -> bool:
            # next[i] is the first position at least distance after i.
            nxt = [0] * (2 * n)
            j = 1
            for i in range(2 * n):
                if j <= i:
                    j = i + 1
                target = extended[i] + distance
                while extended[j] < target:
                    j += 1
                nxt[i] = j

            jumps = [nxt]
            for _ in range(1, (k - 1).bit_length()):
                previous = jumps[-1]
                jumps.append([previous[x] if x < 2 * n else 2 * n
                              for x in previous])

            steps = k - 1
            for start in range(n):
                current = start
                bit = 0
                remaining = steps
                while remaining and current < 2 * n:
                    if remaining & 1:
                        current = jumps[bit][current]
                    remaining >>= 1
                    bit += 1
                if (current < start + n and
                        extended[current] <= extended[start] + perimeter - distance):
                    return True
            return False

        low, high = 0, perimeter // k
        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1
        return low

