from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        representative = [-1] * (threshold + 1)
        for i, value in enumerate(nums):
            if value > threshold:
                continue
            multiple = value
            while multiple <= threshold:
                j = representative[multiple]
                if j == -1:
                    representative[multiple] = i
                else:
                    union(i, j)
                multiple += value

        return sum(1 for i in range(n) if find(i) == i)

