from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix(x: int) -> int:
            if x <= 0:
                return 0
            total = 0
            lo = 1
            steps = 1
            while lo <= x:
                hi = min(x, lo * 4 - 1)
                total += (hi - lo + 1) * steps
                lo *= 4
                steps += 1
            return total

        def depth(x: int) -> int:
            d = 0
            while x:
                x //= 4
                d += 1
            return d

        ans = 0
        for l, r in queries:
            work = prefix(r) - prefix(l - 1)
            ans += max((work + 1) // 2, depth(r))
        return ans

