from typing import List
from bisect import bisect_left

class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        target = tuple(coordinates[k])

        # Process x increasingly; descending y for ties prevents selecting
        # two points with the same x in a strictly increasing subsequence.
        points = sorted(coordinates, key=lambda p: (p[0], -p[1]))
        tails = []
        left = 0
        for x, y in points:
            pos = bisect_left(tails, y)
            if (x, y) == target:
                left = pos + 1
            if pos == len(tails):
                tails.append(y)
            else:
                tails[pos] = y

        # Reverse the x direction. Ascending y for ties (equivalently,
        # descending -y) likewise prevents using two equal-x points.
        points.sort(key=lambda p: (-p[0], p[1]))
        tails = []
        right = 0
        for x, y in points:
            value = -y
            pos = bisect_left(tails, value)
            if (x, y) == target:
                right = pos + 1
            if pos == len(tails):
                tails.append(value)
            else:
                tails[pos] = value

        return left + right - 1

