import sys

def main():
    input=sys.stdin.readline
    N,K,X=map(int,input().split())
    T=list(map(int,input().split()))
    INF=10**40
    # dp[j][i]: dict of transformed last date u = shipment_day - j*X
    dp=[[{} for _ in range(N+1)] for _ in range(N+1)]
    dp[0][0]={-INF:0}
    for j in range(1,N+1):
        shift=j*X
        for i in range(N+1):
            if not dp[j-1][i]:
                continue
            # ship the next size s orders
            for s in range(1,min(K,N-i)+1):
                end=i+s-1
                threshold=T[end]-shift
                out=dp[j][i+s]
                added_sum=sum(T[i:i+s])
                batch_base=s*shift-added_sum
                for u,cost in dp[j-1][i].items():
                    nu=max(u,threshold)
                    val=cost+batch_base+s*nu
                    old=out.get(nu,INF)
                    if val<old:
                        out[nu]=val
    ans=min(dp[j][N].get(u,INF) for j in range(1,N+1) for u in dp[j][N])
    print(ans)

if __name__=='__main__': main()

