class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        m, n = len(board), len(board[0])

        # For any selected row, at most two columns are occupied by the
        # other rooks, so one of its three best cells is always available.
        top = []
        for row in board:
            cols = sorted(range(n), key=row.__getitem__, reverse=True)[:3]
            top.append([(row[j], j) for j in cols])

        best = -10**30
        for r1 in range(m - 2):
            for r2 in range(r1 + 1, m - 1):
                for r3 in range(r2 + 1, m):
                    for v1, c1 in top[r1]:
                        for v2, c2 in top[r2]:
                            if c1 == c2:
