class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        events.sort(key=lambda event: int(event[1]))
        mentions = [0] * numberOfUsers
        online = [True] * numberOfUsers
        offline_until = [0] * numberOfUsers

        i = 0
        while i < len(events):
            timestamp = int(events[i][1])
            j = i
            while j < len(events) and int(events[j][1]) == timestamp:
                j += 1

            # Restore users whose offline period ends at or before this time.
            for user in range(numberOfUsers):
                if not online[user] and offline_until[user] <= timestamp:
                    online[user] = True

            # Process status changes before messages at this timestamp.
            for k in range(i, j):
                event_type, _, value = events[k]
                if event_type == "OFFLINE":
                    user = int(value)
                    online[user] = False
                    offline_until[user] = timestamp + 60

            for k in range(i, j):
                event_type, _, value = events[k]
                if event_type != "MESSAGE":
                    continue
                if value == "ALL":
                    for user in range(numberOfUsers):
                        mentions[user] += 1
                elif value == "HERE":
                    for user in range(numberOfUsers):
                        if online[user]:
                            mentions[user] += 1
                else:
                    for token in value.split():
                        mentions[int(token[2:])] += 1

            i = j

        return mentions

