from typing import List

class Solution:
    def maxPossibleScore(self, start: List[int], d: int) -> int:
        start.sort()
        n = len(start)

        def feasible(score: int) -> bool:
            chosen = start[0]
            for left in start[1:]:
                chosen = max(left, chosen + score)
                if chosen > left + d:
                    return False
            return True

        lo, hi = 0, (start[-1] + d - start[0]) // (n - 1) + 1
        while lo + 1 < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid
        return lo

