from typing import List
class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        prefixes = []
        p = 0
        for x in skill:
            prefixes.append((p, x))
            p += x
        start = 0
        for j in range(1, len(mana)):
            a, b = mana[j-1], mana[j]
            start += max(before * (a-b) + duration * a for before, duration in prefixes)
        return start + p * mana[-1]

